import networkx as nx
import random

def find_graph():
    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(21))

        # Degrees: 20 vertices of degree 3, 1 vertex of degree 4
        degrees = [3] * 20 + [4]

        # Try to create a random graph with these degrees
        # Using configuration model
        stubs = []
        for i, d in enumerate(degrees):
            stubs.extend([i] * d)

        random.shuffle(stubs)

        edges = []
        for i in range(0, len(stubs), 2):
            u, v = stubs[i], stubs[i+1]
            if u != v and not G.has_edge(u, v):
                edges.append((u, v))
                G.add_edge(u, v)
            else:
                break
        else:
            # Check girth
            if nx.girth(G) >= 6:
                return list(G.edges())
    return None

