def check_graph(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(n):
        d = len(adj[i])
        if not (3 <= d <= 5):
            return False, f"Vertex {i} has degree {d}"

    # Check girth
    for start_node in range(n):
        dist = [-1] * n
        dist[start_node] = 0
        queue = [start_node]
        parent = [-1] * n

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < 6:
                        return False, f"Cycle of length {dist[u] + dist[v] + 1} found"
    return True, "OK"

